import { ProfileStatsCard } from "@/components/design-for-ai/card-profile-stats";

<ProfileStatsCard
  name="Mara Okonkwo"
  role="Type designer"
  location="Lisbon, PT"
  timeZone="Europe/Lisbon"
  bio="Draws letters for screens people read at 2am."
  stats={[
    { label: "Followers", value: 12481, tracksFollow: true },
    { label: "Following", value: 318 },
    { label: "Typefaces", value: 27 },
  ]}
  followed={isFollowing}
  onFollowChange={(next) => (next ? api.follow(id) : api.unfollow(id))}
  onMessage={() => openThread(id)}
/>

